    /// Resized reports the size a stack or tab bar gives its screens. Bottom is
    /// how much of that height a bar covers (iOS tabs run under the tab bar);
    /// content should keep clear of it.
    public struct Resized: Equatable {
        public var tag: UInt32
        public var w: Float
        public var h: Float
        public var bottom: Float

        public init(tag: UInt32 = 0, w: Float = 0, h: Float = 0, bottom: Float = 0) {
            self.tag = tag
            self.w = w
            self.h = h
            self.bottom = bottom
        }

        public func write(to w: inout WireWriter) {
            w.uint(UInt64(self.tag))
            w.float32(self.w)
            w.float32(self.h)
            w.float32(self.bottom)
        }

        public static func read(from r: inout WireReader) throws -> Resized {
            var m = Resized()
            m.tag = UInt32(try r.uint(max: 4294967295))
            m.w = try r.float32()
            m.h = try r.float32()
            m.bottom = try r.float32()
            return m
        }
    }

    /// Changed reports an input's new text.
    public struct Changed: Equatable {
        public var tag: UInt32
        public var text: String

        public init(tag: UInt32 = 0, text: String = "") {
            self.tag = tag
            self.text = text
        }

        public func write(to w: inout WireWriter) {
            w.uint(UInt64(self.tag))
            w.string(self.text)
        }

        public static func read(from r: inout WireReader) throws -> Changed {
            var m = Changed()
            m.tag = UInt32(try r.uint(max: 4294967295))
            m.text = try r.string()
            return m
        }
    }

    /// MeasureText asks the host for a text's size (synchronous host call).
    public struct MeasureText: Equatable {
        public var text: String
        public var font: Font
        public var maxWidth: Float
        public var lines: UInt32

        public init(text: String = "", font: Font = Font(), maxWidth: Float = 0, lines: UInt32 = 0) {
            self.text = text
            self.font = font
            self.maxWidth = maxWidth
            self.lines = lines
        }

        public func write(to w: inout WireWriter) {
            w.string(self.text)
            self.font.write(to: &w)
            w.float32(self.maxWidth)
            w.uint(UInt64(self.lines))
        }

        public static func read(from r: inout WireReader) throws -> MeasureText {
            var m = MeasureText()
            m.text = try r.string()
            m.font = try Font.read(from: &r)
            m.maxWidth = try r.float32()
            m.lines = UInt32(try r.uint(max: 4294967295))
            return m
        }
    }

    /// TextSize answers MeasureText.
    public struct TextSize: Equatable {
        public var w: Float
        public var h: Float

        public init(w: Float = 0, h: Float = 0) {
            self.w = w
            self.h = h
        }

        public func write(to w: inout WireWriter) {
            w.float32(self.w)
            w.float32(self.h)
        }

        public static func read(from r: inout WireReader) throws -> TextSize {
            var m = TextSize()
            m.w = try r.float32()
            m.h = try r.float32()
            return m
        }
    }

    /// PluginCall asks a native plugin to run a method (synchronous host call).
    /// The host answers at once with PluginAck and sends the outcome later as a
    /// PluginResult with the same ID. Args and results are JSON.
    public struct PluginCall: Equatable {
        public var id: UInt64
        public var plugin: String
        public var method: String
        public var args: String

        public init(id: UInt64 = 0, plugin: String = "", method: String = "", args: String = "") {
            self.id = id
            self.plugin = plugin
            self.method = method
            self.args = args
        }

        public func write(to w: inout WireWriter) {
            w.uint(UInt64(self.id))
            w.string(self.plugin)
            w.string(self.method)
            w.string(self.args)
        }

        public static func read(from r: inout WireReader) throws -> PluginCall {
            var m = PluginCall()
            m.id = try r.uint()
            m.plugin = try r.string()
            m.method = try r.string()
            m.args = try r.string()
            return m
        }
    }

    /// PluginAck answers PluginCall: Err is empty when the call started.
    public struct PluginAck: Equatable {
        public var err: String

        public init(err: String = "") {
            self.err = err
        }

        public func write(to w: inout WireWriter) {
            w.string(self.err)
        }

        public static func read(from r: inout WireReader) throws -> PluginAck {
            var m = PluginAck()
            m.err = try r.string()
            return m
        }
    }

    /// PluginResult is a plugin call's outcome. A failure has a Code
    /// ("unavailable", "cancelled", "denied", "not_found", "failed") and Err.
    public struct PluginResult: Equatable {
        public var id: UInt64
        public var value: String
        public var code: String
        public var err: String

        public init(id: UInt64 = 0, value: String = "", code: String = "", err: String = "") {
            self.id = id
            self.value = value
            self.code = code
            self.err = err
        }

        public func write(to w: inout WireWriter) {
            w.uint(UInt64(self.id))
            w.string(self.value)
            w.string(self.code)
            w.string(self.err)
        }

        public static func read(from r: inout WireReader) throws -> PluginResult {
            var m = PluginResult()
            m.id = try r.uint()
            m.value = try r.string()
            m.code = try r.string()
            m.err = try r.string()
            return m
        }
    }

