    /// Op changes one native view.
    public indirect enum Op: Equatable {
        case create(Create)
        case destroy(Destroy)
        case children(Children)
        case frame(Frame)
        case box(Box)
        case text(Text)
        case image(Image)
        case input(Input)
        case screen(Screen)
        case tabItem(TabItem)
        case tabSelect(TabSelect)
        case chrome(Chrome)
        case present(Present)
        case scroll(Scroll)
        case `switch`(Switch)
        case spinner(Spinner)

        public static func write(_ v: Op?, to w: inout WireWriter) {
            switch v {
            case nil:
                w.uint(0)
            case .create(let x)?:
                w.uint(1)
                x.write(to: &w)
            case .destroy(let x)?:
                w.uint(2)
                x.write(to: &w)
            case .children(let x)?:
                w.uint(3)
                x.write(to: &w)
            case .frame(let x)?:
                w.uint(4)
                x.write(to: &w)
            case .box(let x)?:
                w.uint(5)
                x.write(to: &w)
            case .text(let x)?:
                w.uint(6)
                x.write(to: &w)
            case .image(let x)?:
                w.uint(7)
                x.write(to: &w)
            case .input(let x)?:
                w.uint(8)
                x.write(to: &w)
            case .screen(let x)?:
                w.uint(9)
                x.write(to: &w)
            case .tabItem(let x)?:
                w.uint(10)
                x.write(to: &w)
            case .tabSelect(let x)?:
                w.uint(11)
                x.write(to: &w)
            case .chrome(let x)?:
                w.uint(12)
                x.write(to: &w)
            case .present(let x)?:
                w.uint(13)
                x.write(to: &w)
            case .scroll(let x)?:
                w.uint(14)
                x.write(to: &w)
            case .switch(let x)?:
                w.uint(15)
                x.write(to: &w)
            case .spinner(let x)?:
                w.uint(16)
                x.write(to: &w)
            }
        }

        public static func read(from r: inout WireReader) throws -> Op? {
            switch try r.uint() {
            case 0:
                return nil
            case 1:
                return .create(try Create.read(from: &r))
            case 2:
                return .destroy(try Destroy.read(from: &r))
            case 3:
                return .children(try Children.read(from: &r))
            case 4:
                return .frame(try Frame.read(from: &r))
            case 5:
                return .box(try Box.read(from: &r))
            case 6:
                return .text(try Text.read(from: &r))
            case 7:
                return .image(try Image.read(from: &r))
            case 8:
                return .input(try Input.read(from: &r))
            case 9:
                return .screen(try Screen.read(from: &r))
            case 10:
                return .tabItem(try TabItem.read(from: &r))
            case 11:
                return .tabSelect(try TabSelect.read(from: &r))
            case 12:
                return .chrome(try Chrome.read(from: &r))
            case 13:
                return .present(try Present.read(from: &r))
            case 14:
                return .scroll(try Scroll.read(from: &r))
            case 15:
                return .switch(try Switch.read(from: &r))
            case 16:
                return .spinner(try Spinner.read(from: &r))
            default:
                throw WireError.variant
            }
        }
    }

    /// Any top-level message in this schema.
    public indirect enum Message: Equatable {
        case commit(Commit)
        case viewport(Viewport)
        case press(Press)
        case scrolled(Scrolled)
        case popped(Popped)
        case dismissed(Dismissed)
        case selected(Selected)
        case resized(Resized)
        case changed(Changed)
        case measureText(MeasureText)
        case textSize(TextSize)
        case pluginCall(PluginCall)
        case pluginAck(PluginAck)
        case pluginResult(PluginResult)
        case toggled(Toggled)
        case refresh(Refresh)

        public static func write(_ v: Message?, to w: inout WireWriter) {
            switch v {
            case nil:
                w.uint(0)
            case .commit(let x)?:
                w.uint(1)
                x.write(to: &w)
            case .viewport(let x)?:
                w.uint(2)
                x.write(to: &w)
            case .press(let x)?:
                w.uint(3)
                x.write(to: &w)
            case .scrolled(let x)?:
                w.uint(4)
                x.write(to: &w)
            case .popped(let x)?:
                w.uint(5)
                x.write(to: &w)
            case .dismissed(let x)?:
                w.uint(6)
                x.write(to: &w)
            case .selected(let x)?:
                w.uint(7)
                x.write(to: &w)
            case .resized(let x)?:
                w.uint(8)
                x.write(to: &w)
            case .changed(let x)?:
                w.uint(9)
                x.write(to: &w)
            case .measureText(let x)?:
                w.uint(10)
                x.write(to: &w)
            case .textSize(let x)?:
                w.uint(11)
                x.write(to: &w)
            case .pluginCall(let x)?:
                w.uint(12)
                x.write(to: &w)
            case .pluginAck(let x)?:
                w.uint(13)
                x.write(to: &w)
            case .pluginResult(let x)?:
                w.uint(14)
                x.write(to: &w)
            case .toggled(let x)?:
                w.uint(15)
                x.write(to: &w)
            case .refresh(let x)?:
                w.uint(16)
                x.write(to: &w)
            }
        }

        public static func read(from r: inout WireReader) throws -> Message? {
            switch try r.uint() {
            case 0:
                return nil
            case 1:
                return .commit(try Commit.read(from: &r))
            case 2:
                return .viewport(try Viewport.read(from: &r))
            case 3:
                return .press(try Press.read(from: &r))
            case 4:
                return .scrolled(try Scrolled.read(from: &r))
            case 5:
                return .popped(try Popped.read(from: &r))
            case 6:
                return .dismissed(try Dismissed.read(from: &r))
            case 7:
                return .selected(try Selected.read(from: &r))
            case 8:
                return .resized(try Resized.read(from: &r))
            case 9:
                return .changed(try Changed.read(from: &r))
            case 10:
                return .measureText(try MeasureText.read(from: &r))
            case 11:
                return .textSize(try TextSize.read(from: &r))
            case 12:
                return .pluginCall(try PluginCall.read(from: &r))
            case 13:
                return .pluginAck(try PluginAck.read(from: &r))
            case 14:
                return .pluginResult(try PluginResult.read(from: &r))
            case 15:
                return .toggled(try Toggled.read(from: &r))
            case 16:
                return .refresh(try Refresh.read(from: &r))
            default:
                throw WireError.variant
            }
        }

        /// The message's wire encoding: its id, then its fields.
        public func encode() -> [UInt8] {
            var w = WireWriter()
            Message.write(self, to: &w)
            return w.bytes
        }

        /// Reads exactly one message.
        public static func decode(_ bytes: [UInt8]) throws -> Message {
            var r = WireReader(bytes)
            guard let m = try read(from: &r) else { throw WireError.variant }
            try r.done()
            return m
        }
    }
}
